import yaml from "js-yaml";

export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout: string;
  /** Any additional user-defined keys pass through untouched. */
  [key: string]: unknown;
}

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

const FM_DELIMITER = /^---\s*\r?\n/;

/**
 * Parse a Markdown document with optional YAML frontmatter delimited by `---`.
 * Missing/absent frontmatter yields sensible defaults.
 */
export function parseFrontmatter(source: string): ParsedDocument {
  let raw: Record<string, unknown> = {};
  let body = source;

  if (FM_DELIMITER.test(source)) {
    const end = source.indexOf("\n---", source.indexOf("\n"));
    if (end !== -1) {
      const yamlBlock = source.slice(source.indexOf("\n") + 1, end);
      const rest = source.slice(end + 4).replace(/^\s*\r?\n/, "");
      const loaded = yaml.load(yamlBlock);
      if (loaded !== null && typeof loaded === "object" && !Array.isArray(loaded)) {
        raw = loaded as Record<string, unknown>;
        body = rest;
      }
    }
  }

  return { frontmatter: normalize(raw), body };
}

function normalize(raw: Record<string, unknown>): Frontmatter {
  const { title, date, tags, draft, layout, ...extra } = raw;
  return {
    ...extra,
    title: typeof title === "string" ? title : "",
    date: coerceDate(date),
    tags: coerceTags(tags),
    draft: draft === true,
    layout: typeof layout === "string" ? layout : "default",
  };
}

function coerceDate(value: unknown): Date | null {
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  if (typeof value === "string" || typeof value === "number") {
    const d = new Date(value);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function coerceTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map(String).map((t) => t.trim()).filter(Boolean);
  }
  if (typeof value === "string") {
    return value.split(",").map((t) => t.trim()).filter(Boolean);
  }
  return [];
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code, lang) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

marked.setOptions({ gfm: true });

/** Render Markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(md: string): string {
  return marked.parse(md, { async: false }) as string;
}

import Handlebars from "handlebars";
import { promises as fs } from "node:fs";
import path from "node:path";

export interface TemplateEngine {
  /** Render `context` through layout `name` (falls back to "default"). */
  render(name: string, context: Record<string, unknown>): string;
  hasLayout(name: string): boolean;
}

/**
 * Template directory conventions:
 *   templates/layouts/*.hbs   -> named layouts (frontmatter `layout: post` -> layouts/post.hbs)
 *   templates/partials/*.hbs  -> registered as partials by filename
 *   templates/*.hbs           -> also usable as layouts (top-level fallback)
 */
export async function createTemplateEngine(templateDir: string): Promise<TemplateEngine> {
  const hb = Handlebars.create();
  registerHelpers(hb);

  const layouts = new Map<string, Handlebars.TemplateDelegate>();

  const partialsDir = path.join(templateDir, "partials");
  for (const file of await listHbs(partialsDir)) {
    const name = path.basename(file, path.extname(file));
    hb.registerPartial(name, await fs.readFile(file, "utf8"));
  }

  const layoutsDir = path.join(templateDir, "layouts");
  for (const file of await listHbs(layoutsDir)) {
    const name = path.basename(file, path.extname(file));
    layouts.set(name, hb.compile(await fs.readFile(file, "utf8")));
  }
  // Top-level templates act as layouts too (lower precedence).
  for (const file of await listHbs(templateDir)) {
    const name = path.basename(file, path.extname(file));
    if (!layouts.has(name)) {
      layouts.set(name, hb.compile(await fs.readFile(file, "utf8")));
    }
  }

  return {
    hasLayout: (name) => layouts.has(name),
    render(name, context) {
      const template = layouts.get(name) ?? layouts.get("default");
      if (!template) {
        throw new Error(
          `No layout "${name}" and no "default" layout found in ${templateDir}`
        );
      }
      return template(context);
    },
  };
}

function registerHelpers(hb: typeof Handlebars): void {
  hb.registerHelper("formatDate", (date: unknown, fmt?: unknown) => {
    if (!(date instanceof Date)) return "";
    if (fmt === "iso") return date.toISOString();
    return date.toISOString().slice(0, 10);
  });
  hb.registerHelper("eq", (a: unknown, b: unknown) => a === b);
  hb.registerHelper("json", (v: unknown) => JSON.stringify(v));
}

async function listHbs(dir: string): Promise<string[]> {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    return entries
      .filter((e) => e.isFile() && /\.(hbs|handlebars)$/.test(e.name))
      .map((e) => path.join(dir, e.name))
      .sort();
  } catch {
    return [];
  }
}

import type { Page } from "./build.js";

export interface RssOptions {
  title: string;
  description: string;
  siteUrl: string;
}

const escapeXml = (s: string): string =>
  s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");

/** Generate an RSS 2.0 feed from published (non-draft) pages, newest first. */
export function generateRss(pages: Page[], opts: RssOptions): string {
  const base = opts.siteUrl.replace(/\/+$/, "");
  const items = pages
    .filter((p) => !p.frontmatter.draft)
    .sort((a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0))
    .map((p) => {
      const url = `${base}${p.url}`;
      const pubDate = p.frontmatter.date ? `\n      <pubDate>${p.frontmatter.date.toUTCString()}</pubDate>` : "";
      return `    <item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid>${escapeXml(url)}</guid>${pubDate}
      <description>${escapeXml(p.html)}</description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${escapeXml(opts.title)}</title>
    <link>${escapeXml(base)}</link>
    <description>${escapeXml(opts.description)}</description>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>
`;
}

import { promises as fs } from "node:fs";
import path from "node:path";
import { parseFrontmatter, type Frontmatter } from "./frontmatter.js";
import { renderMarkdown } from "./markdown.js";
import { createTemplateEngine } from "./templates.js";
import { generateRss } from "./rss.js";

export interface BuildOptions {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  /** Include pages marked `draft: true` (default false). */
  drafts?: boolean;
  siteTitle?: string;
  siteDescription?: string;
  siteUrl?: string;
  /** Extra HTML injected before </body> of every page (used for live reload). */
  injectHtml?: string;
}

export interface Page {
  /** Path of the source file relative to sourceDir. */
  sourcePath: string;
  /** Site-absolute URL, e.g. "/posts/hello/". */
  url: string;
  /** Output path relative to outputDir. */
  outputPath: string;
  frontmatter: Frontmatter;
  /** Rendered Markdown body (no layout). */
  html: string;
}

export interface BuildResult {
  pages: Page[];
  tagPages: string[];
  outputFiles: string[];
}

export async function build(opts: BuildOptions): Promise<BuildResult> {
  const engine = await createTemplateEngine(opts.templateDir);
  const site = {
    title: opts.siteTitle ?? "Site",
    description: opts.siteDescription ?? "",
    url: (opts.siteUrl ?? "http://localhost:3000").replace(/\/+$/, ""),
  };

  const files = await walkMarkdown(opts.sourceDir);
  const pages: Page[] = [];
  for (const file of files) {
    const rel = path.relative(opts.sourceDir, file);
    const { frontmatter, body } = parseFrontmatter(await fs.readFile(file, "utf8"));
    if (frontmatter.draft && !opts.drafts) continue;
    const { url, outputPath } = routeFor(rel);
    pages.push({ sourcePath: rel, url, outputPath, frontmatter, html: renderMarkdown(body) });
  }
  pages.sort(
    (a, b) =>
      (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0) ||
      a.sourcePath.localeCompare(b.sourcePath)
  );

  await fs.rm(opts.outputDir, { recursive: true, force: true });
  await fs.mkdir(opts.outputDir, { recursive: true });

  const outputFiles: string[] = [];
  const writeOut = async (relPath: string, content: string) => {
    const abs = path.join(opts.outputDir, relPath);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    await fs.writeFile(abs, content, "utf8");
    outputFiles.push(relPath);
  };

  // Pages
  for (const page of pages) {
    const layout = engine.hasLayout(page.frontmatter.layout) ? page.frontmatter.layout : "default";
    let html = engine.render(layout, {
      content: page.html,
      page: { ...page.frontmatter, url: page.url },
      site,
      pages: publicPageList(pages),
    });
    html = inject(html, opts.injectHtml);
    await writeOut(page.outputPath, html);
  }

  // Tag index pages
  const tags = collectTags(pages);
  const tagPages: string[] = [];
  for (const [tag, tagged] of tags) {
    const url = `/tags/${slugify(tag)}/`;
    const layout = engine.hasLayout("tag") ? "tag" : "default";
    let html = engine.render(layout, {
      content: "",
      tag,
      page: { title: `Tag: ${tag}`, url, tags: [], date: null, draft: false },
      site,
      pages: publicPageList(tagged),
    });
    html = inject(html, opts.injectHtml);
    await writeOut(path.join("tags", slugify(tag), "index.html"), html);
    tagPages.push(url);
  }

  // RSS
  await writeOut(
    "feed.xml",
    generateRss(pages, { title: site.title, description: site.description, siteUrl: site.url })
  );

  return { pages, tagPages, outputFiles };
}

/** "posts/hello.md" -> url "/posts/hello/", output "posts/hello/index.html".
 *  "index.md" -> "/" -> "index.html". */
export function routeFor(relSourcePath: string): { url: string; outputPath: string } {
  const noExt = relSourcePath.replace(/\.(md|markdown)$/i, "");
  const parts = noExt.split(path.sep).map(slugifyPathSegment);
  if (parts[parts.length - 1] === "index") parts.pop();
  const url = parts.length ? `/${parts.join("/")}/` : "/";
  const outputPath = path.join(...parts, "index.html");
  return { url, outputPath };
}

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function slugifyPathSegment(s: string): string {
  const slug = slugify(s);
  return slug || "untitled";
}

export function collectTags(pages: Page[]): Map<string, Page[]> {
  const map = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      const list = map.get(tag) ?? [];
      list.push(page);
      map.set(tag, list);
    }
  }
  return map;
}

function publicPageList(pages: Page[]) {
  return pages.map((p) => ({ ...p.frontmatter, url: p.url }));
}

function inject(html: string, snippet?: string): string {
  if (!snippet) return html;
  return html.includes("</body>")
    ? html.replace("</body>", `${snippet}\n</body>`)
    : html + snippet;
}

async function walkMarkdown(dir: string): Promise<string[]> {
  const out: string[] = [];
  async function walk(current: string): Promise<void> {
    let entries;
    try {
      entries = await fs.readdir(current, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) await walk(full);
      else if (/\.(md|markdown)$/i.test(entry.name)) out.push(full);
    }
  }
  await walk(dir);
  return out.sort();
}

import http from "node:http";
import { promises as fs } from "node:fs";
import path from "node:path";
import chokidar from "chokidar";
import { WebSocketServer, WebSocket } from "ws";
import { build, type BuildOptions } from "./build.js";

export const LIVE_RELOAD_SNIPPET = `<script>
(() => {
  const connect = () => {
    const ws = new WebSocket("ws://" + location.host + "/__livereload");
    ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
    ws.onclose = () => setTimeout(connect, 1000);
  };
  connect();
})();
</script>`;

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".xml": "application/xml; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
  ".woff2": "font/woff2",
};

export interface DevServer {
  port: number;
  close(): Promise<void>;
}

/**
 * Serve `outputDir` over HTTP, rebuild on changes to source/template dirs
 * (via chokidar), and notify browsers over WebSocket to reload.
 */
export async function serve(
  opts: BuildOptions & { port?: number }
): Promise<DevServer> {
  const buildOpts: BuildOptions = { ...opts, injectHtml: LIVE_RELOAD_SNIPPET };
  await build(buildOpts);

  const server = http.createServer(async (req, res) => {
    try {
      const urlPath = decodeURIComponent((req.url ?? "/").split("?")[0] ?? "/");
      const filePath = resolveFile(opts.outputDir, urlPath);
      if (!filePath) {
        res.writeHead(403).end("Forbidden");
        return;
      }
      const content = await readWithIndexFallback(filePath);
      if (content === null) {
        res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
        res.end(`<h1>404 Not Found</h1>${LIVE_RELOAD_SNIPPET}`);
        return;
      }
      res.writeHead(200, {
        "Content-Type": MIME[path.extname(content.path).toLowerCase()] ?? "application/octet-stream",
        "Cache-Control": "no-store",
      });
      res.end(content.data);
    } catch (err) {
      res.writeHead(500).end(String(err));
    }
  });

  const wss = new WebSocketServer({ noServer: true });
  server.on("upgrade", (req, socket, head) => {
    if (req.url === "/__livereload") {
      wss.handleUpgrade(req, socket, head, (ws) => wss.emit("connection", ws, req));
    } else {
      socket.destroy();
    }
  });

  const broadcast = (msg: string) => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send(msg);
    }
  };

  let pending: NodeJS.Timeout | null = null;
  const watcher = chokidar.watch([opts.sourceDir, opts.templateDir], {
    ignoreInitial: true,
  });
  watcher.on("all", () => {
    if (pending) clearTimeout(pending);
    pending = setTimeout(async () => {
      try {
        await build(buildOpts);
        broadcast("reload");
        console.log("[sitegen] rebuilt, reload sent");
      } catch (err) {
        console.error("[sitegen] rebuild failed:", err);
      }
    }, 100);
  });

  const port = await listen(server, opts.port ?? 3000);
  console.log(`[sitegen] dev server at http://localhost:${port}`);

  return {
    port,
    async close() {
      if (pending) clearTimeout(pending);
      await watcher.close();
      for (const client of wss.clients) client.terminate();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve()))
      );
    },
  };
}

function resolveFile(root: string, urlPath: string): string | null {
  const resolved = path.resolve(root, "." + path.posix.normalize("/" + urlPath));
  return resolved.startsWith(path.resolve(root)) ? resolved : null;
}

async function readWithIndexFallback(
  filePath: string
): Promise<{ data: Buffer; path: string } | null> {
  const candidates = [filePath, path.join(filePath, "index.html")];
  for (const candidate of candidates) {
    try {
      const stat = await fs.stat(candidate);
      if (stat.isFile()) return { data: await fs.readFile(candidate), path: candidate };
    } catch {
      /* try next */
    }
  }
  return null;
}

function listen(server: http.Server, port: number): Promise<number> {
  return new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, () => {
      const addr = server.address();
      resolve(typeof addr === "object" && addr ? addr.port : port);
    });
  });
}

#!/usr/bin/env node
import { fileURLToPath } from "node:url";
import { build, type BuildOptions } from "./build.js";
import { serve } from "./server.js";

export interface CliOptions extends BuildOptions {
  command: "build" | "serve";
  port: number;
  help: boolean;
}

export const USAGE = `sitegen - static site generator

Usage:
  sitegen build [options]   Build the site once
  sitegen serve [options]   Build, serve, watch, and live-reload

Options:
  -s, --source <dir>       Markdown source directory      (default: content)
  -t, --templates <dir>    Handlebars template directory  (default: templates)
  -o, --output <dir>       Output directory               (default: dist)
  -p, --port <n>           Dev server port                (default: 3000)
      --drafts             Include pages marked draft: true
      --site-title <s>     Site title (used in RSS)       (default: Site)
      --site-desc <s>      Site description (used in RSS)
      --site-url <url>     Canonical site URL (used in RSS)
  -h, --help               Show this help
`;

/** Parse argv (without node/script prefix) into CLI options. Throws on bad input. */
export function parseArgs(argv: string[]): CliOptions {
  const opts: CliOptions = {
    command: "build",
    sourceDir: "content",
    templateDir: "templates",
    outputDir: "dist",
    port: 3000,
    drafts: false,
    siteTitle: "Site",
    siteDescription: "",
    siteUrl: "http://localhost:3000",
    help: false,
  };

  const args = [...argv];
  if (args[0] === "build" || args[0] === "serve") {
    opts.command = args.shift() as "build" | "serve";
  }

  const next = (flag: string): string => {
    const value = args.shift();
    if (value === undefined || value.startsWith("-")) {
      throw new Error(`Missing value for ${flag}`);
    }
    return value;
  };

  while (args.length > 0) {
    const arg = args.shift()!;
    switch (arg) {
      case "-s":
      case "--source":
        opts.sourceDir = next(arg);
        break;
      case "-t":
      case "--templates":
        opts.templateDir = next(arg);
        break;
      case "-o":
      case "--output":
        opts.outputDir = next(arg);
        break;
      case "-p":
      case "--port": {
        const port = Number(next(arg));
        if (!Number.isInteger(port) || port < 0 || port > 65535) {
          throw new Error(`Invalid port: ${port}`);
        }
        opts.port = port;
        break;
      }
      case "--drafts":
        opts.drafts = true;
        break;
      case "--site-title":
        opts.siteTitle = next(arg);
        break;
      case "--site-desc":
        opts.siteDescription = next(arg);
        break;
      case "--site-url":
        opts.siteUrl = next(arg);
        break;
      case "-h":
      case "--help":
        opts.help = true;
        break;
      default:
        throw new Error(`Unknown option: ${arg}`);
    }
  }
  return opts;
}

export async function main(argv: string[]): Promise<number> {
  let opts: CliOptions;
  try {
    opts = parseArgs(argv);
  } catch (err) {
    console.error(String(err instanceof Error ? err.message : err));
    console.error(USAGE);
    return 2;
  }

  if (opts.help) {
    console.log(USAGE);
    return 0;
  }

  try {
    if (opts.command === "serve") {
      await serve(opts);
      return 0; // stays alive via open server handles
    }
    const result = await build(opts);
    console.log(
      `[sitegen] built ${result.pages.length} page(s), ` +
        `${result.tagPages.length} tag page(s), feed.xml -> ${opts.outputDir}`
    );
    return 0;
  } catch (err) {
    console.error("[sitegen] error:", err instanceof Error ? err.message : err);
    return 1;
  }
}

const isDirectRun =
  process.argv[1] && fileURLToPath(import.meta.url) === (await import("node:path")).resolve(process.argv[1]);
if (isDirectRun) {
  process.exitCode = await main(process.argv.slice(2));
}

export { parseFrontmatter, type Frontmatter, type ParsedDocument } from "./frontmatter.js";
export { renderMarkdown } from "./markdown.js";
export { createTemplateEngine, type TemplateEngine } from "./templates.js";
